UPDATE GE_PL_PRCDOC01_M
   SET DLT_YN 	   = 'Y'
 WHERE PRCDOC_SNO = #{PRCDOC_SNO}

mapper.select:
	SELECT 
		PRCDOC_SNO,
		PRCDOC_NO,
		PRCDOC_NM,
		DOC_TYP_CD,
		PRT_NO,
		LAST_UPDR_ID
  	 FROM GE_PL_PRCDOC01_M
	 WHERE PRCDOC_NO = #{PRCDOC_NO}
	   AND DOC_TYP_CD = #{DOC_TYP_CD}
	   AND PRT_NO = #{PRT_NO}
	   AND LAST_UPDR_ID = #{LAST_UPDR_ID}
